async def act(page):
    # Step 1: Navigate (relative) to the Sales Orders grid
    await page.goto('/index.php/admin/sales_order/index/')
    await page.wait_for_load_state('networkidle')

    # Step 2: Try to filter Status = "Complete" if a Status combobox exists (best-effort)
    try:
        status_cb = page.get_by_role('combobox', name='Status')
        await status_cb.select_option(label='Complete')
        # Try to apply the filter by clicking a Search button; fall back to pressing Enter on the combobox
        try:
            await page.get_by_role('button', name='Search').click()
        except Exception:
            try:
                await status_cb.press('Enter')
            except Exception:
                pass
        await page.wait_for_load_state('networkidle')
    except Exception:
        # Combobox not present or selection failed; continue without filtering
        pass

    # Step 3: Try to sort by a likely "Purchased On" column header (toggle clicks to attempt oldest-first)
    for header_name in ('Purchased On', 'Purchased on', 'Purchased'):
        try:
            header = page.get_by_role('columnheader', name=header_name)
            await header.click()
            await page.wait_for_timeout(250)
            # Click again to toggle sort direction (best-effort)
            await header.click()
            await page.wait_for_load_state('networkidle')
            break
        except Exception:
            continue

    # Step 4: Locate the orders table and select the first data row (skip header if present)
    try:
        # Prefer an accessible table named 'Orders' if present, otherwise use the first table
        try:
            table = page.get_by_role('table', name='Orders').first()
        except Exception:
            table = page.get_by_role('table').first()
        rows = table.get_by_role('row')
        row_count = await rows.count()
        if row_count == 0:
            print("")
            return
        # Assume header row exists; choose nth(1) if more than 1 row, else nth(0)
        order_row = rows.nth(1) if row_count > 1 else rows.nth(0)
    except Exception:
        print("")
        return

    # Step 5: From that row, get the first link's href (do not click it)
    href = None
    try:
        links = order_row.get_by_role('link')
        if await links.count() > 0:
            href = await links.first().get_attribute('href')
    except Exception:
        href = None

    if not href:
        print("")
        return

    # Step 6: Navigate to the order view using the href
    await page.goto(href)
    await page.wait_for_load_state('networkidle')

    # Step 7: Extract billing information from common headings or nearby text (best-effort with fallbacks)
    billing_text = None
    heading_candidates = ['Billing Information', 'Billing Address', 'Billing', 'Bill to', 'Bill To', 'Billing Details']
    for hname in heading_candidates:
        try:
            loc = page.get_by_role('heading', name=hname)
            if await loc.count() > 0:
                eh = await loc.first().element_handle()
                if eh:
                    billing_text = await page.evaluate(
                        "(el) => { const sib = el.nextElementSibling || el.parentElement.querySelector('address, .box, .address'); if (sib && sib.innerText) return sib.innerText; return el.parentElement ? el.parentElement.innerText : null; }",
                        eh,
                    )
                    if billing_text and billing_text.strip():
                        break
        except Exception:
            continue

    # Fallback: look for text nodes containing 'Bill to' or 'Billing' and read nearby content
    if not billing_text:
        try:
            nodes = page.get_by_text('Bill to', exact=False)
            if await nodes.count() > 0:
                eh = await nodes.first().element_handle()
                if eh:
                    billing_text = await page.evaluate(
                        "(el) => { const sib = el.nextElementSibling || el.parentElement.querySelector('address, .box, .address'); if (sib && sib.innerText) return sib.innerText; return el.parentElement ? el.parentElement.innerText : null; }",
                        eh,
                    )
        except Exception:
            billing_text = None

    if not billing_text:
        try:
            nodes = page.get_by_text('Billing', exact=False)
            if await nodes.count() > 0:
                eh = await nodes.first().element_handle()
                if eh:
                    billing_text = await page.evaluate(
                        "(el) => { const sib = el.nextElementSibling || el.parentElement.querySelector('address, .box, .address'); if (sib && sib.innerText) return sib.innerText; return el.parentElement ? el.parentElement.innerText : null; }",
                        eh,
                    )
        except Exception:
            billing_text = None

    if not billing_text:
        print("")
        return

    # Step 8: Print the first non-empty line of the billing block as the billing name
    lines = [ln.strip() for ln in billing_text.splitlines() if ln.strip()]
    billing_name = lines[0] if lines else ''
    print(billing_name)

